/**
 * Bulk-safe handler for ContactTrigger.
 *
 * Budget for ≤ 200 records:  2 SOQL, 1 DML  (before + after combined).
 */
public with sharing class ContactTriggerHandler {

    /* ------------------------------------------------------------------ */
    /*  BEFORE INSERT / BEFORE UPDATE                                      */
    /*  • MailingCountry ← Account.BillingCountry  (when blank)           */
    /*  • LeadSource     ← Account.AccountSource    (insert only, blank)  */
    /* ------------------------------------------------------------------ */
    public static void handleBefore() {

        List<Contact> newContacts = (List<Contact>) Trigger.new;

        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // --- 1 SOQL --------------------------------------------------------
        Map<Id, Account> acctById = new Map<Id, Account>(
            [SELECT Id, BillingCountry, AccountSource
             FROM   Account
             WHERE  Id IN :accountIds]
        );

        Boolean isInsert = Trigger.isInsert;

        for (Contact c : newContacts) {
            if (c.AccountId == null) {
                continue;
            }

            Account a = acctById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }

            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /* ------------------------------------------------------------------ */
    /*  AFTER INSERT                                                       */
    /*  If a new Contact carries a Phone and its Account has none,       */
    /*  copy the phone to the Account.  Only the FIRST contact in        */
    /*  trigger order for a given Account performs the write.             */
    /* ------------------------------------------------------------------ */
    public static void handleAfterInsert() {

        List<Contact> newContacts = (List<Contact>) Trigger.new;

        // Only care about contacts that could possibly drive a phone update.
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // --- 2nd SOQL ------------------------------------------------------
        Map<Id, Account> acctById = new Map<Id, Account>(
            [SELECT Id, Phone
             FROM   Account
             WHERE  Id IN :accountIds]
        );

        List<Account> accountsToUpdate = new List<Account>();

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }

            Account a = acctById.get(c.AccountId);
            if (a == null) {
                continue;
            }

            // Because we mutate the SAME Account instance held in the map,
            // once the first contact writes a phone the subsequent contacts
            // for the same account will see a non-blank value and skip –
            // replicating the "re-query" behaviour of the original code.
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            // --- 1 DML -----------------------------------------------------
            update accountsToUpdate;
        }
    }
}
