public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        List<Id> accountIdsToQuery = new List<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                accountIdsToQuery.add(accountId);
            }
        }

        if (accountIdsToQuery.isEmpty()) {
            return result;
        }

        for (Contact contactRecord : [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIdsToQuery
            AND Email != null
            WITH USER_MODE
        ]) {
            String email = contactRecord.Email;

            if (email == null || email.length() == 0) {
                continue;
            }

            String trimmedEmail = email.trim();

            if (trimmedEmail.length() == 0) {
                continue;
            }

            Integer atIndex = trimmedEmail.lastIndexOf('@');

            if (atIndex < 0 || atIndex == trimmedEmail.length() - 1) {
                continue;
            }

            String domain = trimmedEmail.substring(atIndex + 1).toLowerCase();

            if (domain == null || domain.length() == 0) {
                continue;
            }

            List<Contact> contactsForDomain = result.get(domain);

            if (contactsForDomain == null) {
                contactsForDomain = new List<Contact>();
                result.put(domain, contactsForDomain);
            }

            contactsForDomain.add(contactRecord);
        }

        return result;
    }
}
