/**
 * Utility class for parsing free-text supplier payment terms into
 * a net-days integer and for deriving the due date from an invoice date.
 *
 * Recognised patterns (case-insensitive, surrounding whitespace ignored):
 *   NET <digits>   – e.g. "NET 30", "net30", "Net  45"  (1-3 digits)
 *   DUE ON RECEIPT – returns 0
 *
 * Anything else (including null / blank) throws UnsupportedTermsException.
 * A valid NET pattern whose value > 180 throws TermsOutOfRangeException.
 */
public with sharing class PaymentTerms {

    private static final Pattern NET_PATTERN =
        Pattern.compile('^NET\\s*\\d{1,3}$');

    /**
     * Parses a free-text terms string and returns the number of net days.
     *
     * @param terms the raw terms string from the supplier invoice
     * @return the number of net days (0 for "DUE ON RECEIPT")
     * @throws TermsOutOfRangeException  when parsed days exceed 180
     * @throws UnsupportedTermsException when the input cannot be recognised
     */
    public static Integer parseNetDays(String terms) {
        // Null or blank (after trim) → unsupported
        if (terms == null || terms.trim() == '') {
            throw new UnsupportedTermsException(
                'Unsupported payment terms: ' + terms
            );
        }

        // Normalise: trim surrounding whitespace and uppercase for matching
        String normalised = terms.trim().toUpperCase();

        // "DUE ON RECEIPT" → 0 days
        if (normalised == 'DUE ON RECEIPT') {
            return 0;
        }

        // "NET <1-3 digits>" (whitespace between NET and digits optional)
        Matcher m = NET_PATTERN.matcher(normalised);
        if (m.matches()) {
            String digits = normalised.replaceAll('^NET\\s*', '');
            Integer days = Integer.valueOf(digits);

            if (days > 180) {
                throw new TermsOutOfRangeException(
                    'Net days out of range: ' + days
                );
            }

            return days;
        }

        // Anything else → unsupported
        throw new UnsupportedTermsException(
            'Unsupported payment terms: ' + terms
        );
    }

    /**
     * Returns the payment due date by adding the parsed net days to the
     * invoice date. Throws the same exceptions as parseNetDays.
     *
     * @param invoiceDate the invoice creation / receipt date
     * @param terms       the raw free-text terms string
     * @return the due Date (invoiceDate + net days)
     * @throws TermsOutOfRangeException  when parsed days exceed 180
     * @throws UnsupportedTermsException when the input cannot be recognised
     */
    public static Date dueDate(Date invoiceDate, String terms) {
        Integer netDays = parseNetDays(terms);
        return invoiceDate.addDays(netDays);
    }
}
