public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    private static final Set<Schema.DisplayType> NON_FILTERABLE = new Set<Schema.DisplayType>{
        Schema.DisplayType.LongTextArea,
        Schema.DisplayType.MultiPicklist
    };

    private static final Set<Schema.DisplayType> NON_SORTABLE = new Set<Schema.DisplayType>{
        Schema.DisplayType.LongTextArea,
        Schema.DisplayType.MultiPicklist
    };

    /**
     * Builds and executes a single SOQL query against any SObject using
     * equality filters, with SOQL-injection protection and FLS/sharing enforcement.
     */
    public static List<SObject> search(String objectApiName, List<String> fields,
            Map<String, Object> filters, String orderByField, Integer maxRows) {

        // ── Validate maxRows ──────────────────────────────────────────────
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // ── Validate fields list ──────────────────────────────────────────
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // ── Resolve object (case-insensitive) ─────────────────────────────
        if (String.isBlank(objectApiName)) {
            throw new SearchException('objectApiName is required.');
        }

        Schema.SObjectType objectToken = resolveObjectType(objectApiName);
        if (objectToken == null) {
            throw new SearchException('Object "' + objectApiName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objDescribe = objectToken.getDescribe();

        // ── Object-level read access ──────────────────────────────────────
        if (!objDescribe.isAccessible()) {
            throw new SearchException('Running user cannot read "' + objectApiName + '".');
        }

        // ── Build case-insensitive field lookup ───────────────────────────
        Map<String, Schema.SObjectField> allFields = objDescribe.fields.getMap();
        Map<String, Schema.SObjectField> fieldByLower = new Map<String, Schema.SObjectField>();
        for (Map.Entry<String, Schema.SObjectField> entry : allFields.entrySet()) {
            fieldByLower.put(entry.getKey().toLowerCase(), entry.getValue());
        }

        // ── Resolve SELECT fields ─────────────────────────────────────────
        List<String> selectParts = new List<String>{'Id'};
        Set<String> selectedLower = new Set<String>{'id'};

        for (String fName : fields) {
            if (String.isBlank(fName)) {
                throw new SearchException('A field name in fields is blank.');
            }
            String lower = fName.toLowerCase();
            if (!fieldByLower.containsKey(lower)) {
                throw new SearchException('Field "' + fName + '" is not a field of the object.');
            }
            Schema.DescribeFieldResult fr = fieldByLower.get(lower).getDescribe();
            if (!fr.isAccessible()) {
                throw new SearchException('Field "' + fName + '" is not accessible to the running user.');
            }
            if (!selectedLower.contains(lower)) {
                selectParts.add(fr.getName());
                selectedLower.add(lower);
            }
        }

        // ── Build WHERE clause with bind variables ────────────────────────
        String whereClause = '';
        Map<String, Object> binds = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            List<String> whereParts = new List<String>();
            Integer bindIdx = 0;

            for (String filterKey : filters.keySet()) {
                if (String.isBlank(filterKey)) {
                    throw new SearchException('A filter key is blank.');
                }
                String lower = filterKey.toLowerCase();
                if (!fieldByLower.containsKey(lower)) {
                    throw new SearchException(
                        'Filter field "' + filterKey + '" is not a field of the object.');
                }
                Schema.DescribeFieldResult fr = fieldByLower.get(lower).getDescribe();
                if (!fr.isAccessible()) {
                    throw new SearchException(
                        'Filter field "' + filterKey + '" is not accessible to the running user.');
                }
                if (NON_FILTERABLE.contains(fr.getType())) {
                    throw new SearchException(
                        'Filter field "' + filterKey + '" cannot be filtered.');
                }

                String fieldName = fr.getName();
                Object val = filters.get(filterKey);

                if (val == null) {
                    whereParts.add(fieldName + ' = null');
                } else {
                    String bindName = 'bind' + bindIdx;
                    whereParts.add(fieldName + ' = :' + bindName);
                    binds.put(bindName, val);
                    bindIdx++;
                }
            }

            whereClause = ' WHERE ' + String.join(whereParts, ' AND ');
        }

        // ── Build ORDER BY clause ─────────────────────────────────────────
        String orderClause = '';
        if (String.isNotBlank(orderByField)) {
            String lower = orderByField.toLowerCase();
            if (!fieldByLower.containsKey(lower)) {
                throw new SearchException(
                    'Order-by field "' + orderByField + '" is not a field of the object.');
            }
            Schema.DescribeFieldResult fr = fieldByLower.get(lower).getDescribe();
            if (!fr.isAccessible()) {
                throw new SearchException(
                    'Order-by field "' + orderByField + '" is not accessible to the running user.');
            }
            if (NON_SORTABLE.contains(fr.getType())) {
                throw new SearchException(
                    'Order-by field "' + orderByField + '" cannot be sorted.');
            }
            orderClause = ' ORDER BY ' + fr.getName() + ' ASC';
        }

        // ── Assemble and execute the single SOQL query ────────────────────
        String query = 'SELECT ' + String.join(selectParts, ', ')
                     + ' FROM ' + objDescribe.getName()
                     + whereClause
                     + orderClause
                     + ' LIMIT ' + String.valueOf(maxRows);

        try {
            return Database.queryWithBinds(query, binds, System.AccessLevel.USER_MODE);
        } catch (SearchException se) {
            throw se;
        } catch (Exception ex) {
            throw new SearchException(
                'Query execution failed: ' + ex.getMessage());
        }
    }

    // ── Private helpers ───────────────────────────────────────────────────

    /**
     * Case-insensitive lookup of an SObjectType token by API name.
     */
    private static Schema.SObjectType resolveObjectType(String apiName) {
        Map<String, Schema.SObjectType> gd = Schema.getGlobalDescribe();
        String lower = apiName.toLowerCase();

        // Exact-case fast path
        if (gd.containsKey(apiName)) {
            return gd.get(apiName);
        }

        // Case-insensitive fallback
        for (String key : gd.keySet()) {
            if (key.toLowerCase() == lower) {
                return gd.get(key);
            }
        }
        return null;
    }
}
