        for (Request req : requests) {
            if (req.email != null) {
                String trimmed = req.email.trim();
                if (String.isNotBlank(trimmed)) {
                    emailSet.add(trimmed);
                }
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!emailSet.isEmpty()) {
            List<Contact> contacts = [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailSet
                WITH USER_MODE
                ORDER BY CreatedDate ASC
            ];

            for (Contact c : contacts) {
                String key = c.Email.toLowerCase();
                if (!emailToContactId.containsKey(key)) {
                    emailToContactId.put(key, c.Id);
                }
            }
        }

        List<Result> results = new List<Result>(requests.size());

        for (Request req : requests) {
            Result res = new Result();

            String trimmed = req.email != null ? req.email.trim() : null;

            if (String.isNotBlank(trimmed)) {
                String key = trimmed.toLowerCase();
                Id matchedId = emailToContactId.get(key);
                if (matchedId != null) {
                    res.contactId = matchedId;
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                res.contactId = null;
                res.found = false;
            }

            results.add(res);
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label='Email' description='Email address to search for (case-insensitive)' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching Contact, or null if not found')
        public Id contactId;

        @InvocableVariable(label='Found' description='True when a Contact with the given email exists')
        public Boolean found;
    }
}
