public with sharing class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (body == null || body.isBlank()) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        // Validate order number
        if (!root.containsKey('number') || root.get('number') == null) {
            throw new PayloadException('Missing order number');
        }
        String numberVal = String.valueOf(root.get('number'));
        if (numberVal.isBlank()) {
            throw new PayloadException('Blank order number');
        }

        Order order = new Order();
        order.orderNumber = numberVal;
        order.currencyCode = (String) root.get('currency');

        // Parse date
        String dateStr = (String) root.get('date');
        if (dateStr != null && !dateStr.isBlank()) {
            try {
                order.orderDate = Date.valueOf(dateStr);
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // Customer
        order.customerEmail = null;
        if (root.containsKey('customer') && root.get('customer') instanceof Map<String, Object>) {
            Map<String, Object> cust = (Map<String, Object>) root.get('customer');
            if (cust.containsKey('email') && cust.get('email') != null) {
                order.customerEmail = (String) cust.get('email');
            }
        }

        // Initialize lines
        order.lines = new List<Line>();
        order.total = Decimal.valueOf(0);

        // Parse lines
        if (root.containsKey('lines') && root.get('lines') instanceof List<Object>) {
            List<Object> linesArr = (List<Object>) root.get('lines');
            for (Object item : linesArr) {
                if (!(item instanceof Map<String, Object>)) {
                    continue;
                }
                Map<String, Object> lm = (Map<String, Object>) item;

                // Validate sku
                if (!lm.containsKey('sku') || lm.get('sku') == null || String.valueOf(lm.get('sku')).isBlank()) {
                    throw new PayloadException('Missing sku in line');
                }

                // Validate quantity
                if (!lm.containsKey('quantity') || lm.get('quantity') == null) {
                    throw new PayloadException('Missing quantity in line');
                }
                Integer qty;
                Object qtyObj = lm.get('quantity');
                if (qtyObj instanceof Integer) {
                    qty = (Integer) qtyObj;
                } else if (qtyObj instanceof Decimal) {
                    qty = ((Decimal) qtyObj).intValue();
                } else {
                    throw new PayloadException('Invalid quantity in line');
                }
                if (qty <= 0) {
                    throw new PayloadException('Non-positive quantity in line');
                }

                // Validate unitPrice
                if (!lm.containsKey('unitPrice') || lm.get('unitPrice') == null) {
                    throw new PayloadException('Missing unitPrice in line');
                }
                Decimal unitPrice;
                Object priceObj = lm.get('unitPrice');
                if (priceObj instanceof Decimal) {
                    unitPrice = (Decimal) priceObj;
                } else if (priceObj instanceof Integer) {
                    unitPrice = Decimal.valueOf((Integer) priceObj);
                } else {
                    throw new PayloadException('Invalid unitPrice in line');
                }
                if (unitPrice < 0) {
                    throw new PayloadException('Negative unitPrice in line');
                }

                // Discount: missing or null means 0
                Decimal discount = Decimal.valueOf(0);
                if (lm.containsKey('discount') && lm.get('discount') != null) {
                    Object discObj = lm.get('discount');
                    if (discObj instanceof Decimal) {
                        discount = (Decimal) discObj;
                    } else if (discObj instanceof Integer) {
                        discount = Decimal.valueOf((Integer) discObj);
                    }
                }

                Line line = new Line();
                line.sku = (String) lm.get('sku');
                line.quantity = qty;
                line.unitPrice = unitPrice;
                line.discount = discount;

                // lineTotal = quantity * unitPrice * (1 - discount), rounded to 2 dp HALF_UP
                Decimal rawTotal = Decimal.valueOf(qty) * unitPrice * (Decimal.valueOf(1) - discount);
                line.lineTotal = rawTotal.setScale(2, System.RoundingMode.HALF_UP);

                order.total += line.lineTotal;
                order.lines.add(line);
            }
        }

        return order;
    }

    public static String toAcknowledgement(Order order) {
        Integer lineCount = (order.lines != null) ? order.lines.size() : 0;
        Decimal totalVal = (order.total != null) ? order.total : Decimal.valueOf(0);

        String json = '{'
            + '"number":' + JSON.encode(order.orderNumber)
            + ',"status":"RECEIVED"'
            + ',"lineCount":' + String.valueOf(lineCount)
            + ',"total":' + String.valueOf(totalVal)
            + '}';
        return json;
    }
}
