public class PicklistService {

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {}

    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {

        // ---- input validation ----
        if (String.isBlank(objectApiName) || String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Object and field names must not be null or blank.');
        }

        // ---- locate the SObjectType (case-insensitive) ----
        Schema.SObjectType sObjectType = null;
        String searchObj = objectApiName.toLowerCase();
        for (String key : Schema.getGlobalDescribe().keySet()) {
            if (key.toLowerCase() == searchObj) {
                sObjectType = Schema.getGlobalDescribe().get(key);
                break;
            }
        }
        if (sObjectType == null) {
            throw new PicklistServiceException('Object "' + objectApiName + '" does not exist.');
        }

        // ---- locate the field (case-insensitive) ----
        Map<String, Schema.SObjectField> fieldMap = sObjectType.getDescribe().fields.getMap();
        Schema.SObjectField sField = null;
        String searchField = fieldApiName.toLowerCase();
        for (String key : fieldMap.keySet()) {
            if (key.toLowerCase() == searchField) {
                sField = fieldMap.get(key);
                break;
            }
        }
        if (sField == null) {
            throw new PicklistServiceException('Field "' + fieldApiName + '" does not exist on object "' + objectApiName + '".');
        }

        // ---- type check: must be Picklist or Multi-Select Picklist ----
        Schema.DescribeFieldResult fieldDescribe = sField.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException('Field "' + fieldApiName + '" is not a picklist or multi-select picklist.');
        }

        // ---- build the result list ----
        List<PicklistEntry> entries = fieldDescribe.getPicklistValues();
        List<PicklistService.Option> options = new List<PicklistService.Option>();

        if (entries != null) {
            for (PicklistEntry pe : entries) {
                if (pe.isActive()) {
                    options.add(new PicklistService.Option(
                        pe.getValue(),
                        pe.getLabel(),
                        pe.isDefault()
                    ));
                }
            }
        }

        return options;
    }
}
