public class ErpSyncFinalizer implements Finalizer {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        // Determine success or failure from the context.
        // On success getErrorMessage() is null (or blank); on failure it
        // contains the exception message.
        String errorMessage = context.getErrorMessage();
        Boolean jobSucceeded = String.isBlank(errorMessage);

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Attempt__c  = this.attempt
        );

        if (jobSucceeded) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';
            // Truncate to at most 255 characters to fit the field
            log.Error__c = errorMessage.length() > 255
                ? errorMessage.substring(0, 255)
                : errorMessage;

            // Retry if this was fewer than 3 attempts
            if (this.attempt < 3) {
                System.enqueueJob(
                    new ErpAccountSyncJob(this.accountIds, this.attempt + 1)
                );
            }
        }

        insert log;
    }
}
