public without sharing class OpportunityPipelineHandler {

    // Re-entrancy guard: AccountTrigger (after update) re-updates related
    // open Opportunities, which would re-enter this handler.
    private static Boolean isRecursion = false;

    public static void handle() {
        if (isRecursion) return;

        // ---------------------------------------------------------------
        // 1. Collect every Account Id whose pipeline totals may change
        // ---------------------------------------------------------------
        Set<Id> affectedAccountIds = new Set<Id>();

        if (Trigger.isDelete) {
            for (Opportunity opp : (List<Opportunity>) Trigger.old) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUndelete) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isInsert) {
            for (Opportunity opp : (List<Opportunity>) Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    affectedAccountIds.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            List<Opportunity> newOpps   = (List<Opportunity>) Trigger.new;
            Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) Trigger.oldMap;

            for (Opportunity opp : newOpps) {
                Opportunity oldOpp = oldMap.get(opp.Id);

                Boolean relevantChange =
                       opp.AccountId != oldOpp.AccountId
                    || opp.IsClosed  != oldOpp.IsClosed
                    || opp.Amount    != oldOpp.Amount;

                if (relevantChange) {
                    if (opp.AccountId != null) {
                        affectedAccountIds.add(opp.AccountId);
                    }
                    if (oldOpp.AccountId != null && oldOpp.AccountId != opp.AccountId) {
                        affectedAccountIds.add(oldOpp.AccountId);
                    }
                }
            }
        }

        if (affectedAccountIds.isEmpty()) return;

        // ---------------------------------------------------------------
        // 2. Recalculate totals from the database so that multiple DML
        //    statements in one transaction are always reconciled.
        // ---------------------------------------------------------------
        Map<Id, Decimal> amountByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount  = new Map<Id, Integer>();

        for (Opportunity opp : [
            SELECT AccountId, Amount
            FROM   Opportunity
            WHERE  AccountId IN :affectedAccountIds
            AND    IsClosed = false
        ]) {
            Id accId = opp.AccountId;
            Decimal amt = (opp.Amount == null) ? 0 : opp.Amount;

            if (!amountByAccount.containsKey(accId)) {
                amountByAccount.put(accId, 0);
                countByAccount.put(accId, 0);
            }
            amountByAccount.put(accId, amountByAccount.get(accId) + amt);
            countByAccount.put(accId, countByAccount.get(accId) + 1);
        }

        // ---------------------------------------------------------------
        // 3. Write recalculated totals back. Accounts with zero open
        //    opps get explicit 0 (not blank).
        // ---------------------------------------------------------------
        List<Account> accountsToUpdate = new List<Account>();

        for (Id accId : affectedAccountIds) {
            accountsToUpdate.add(new Account(
                Id                       = accId,
                FB_Open_Pipeline__c      = amountByAccount.containsKey(accId)
                                               ? amountByAccount.get(accId) : 0,
                FB_Open_Opportunities__c = countByAccount.containsKey(accId)
                                               ? countByAccount.get(accId) : 0
            ));
        }

        // Guard re-entrancy: the Account DML will fire AccountTrigger which
        // re-updates Opportunities, causing a nested OpportunityTrigger call.
        isRecursion = true;
        try {
            update accountsToUpdate;
        } finally {
            isRecursion = false;
        }
    }
}
