    private class PartialFailGateway implements IBillingGateway {
        public Id failAccountId;
        public String failMessage;
        public List<String> invoiceCalls = new List<String>();

        PartialFailGateway(Id failAccountId, String failMessage) {
            this.failAccountId = failAccountId;
            this.failMessage = failMessage;
        }

        public void authenticate() { /* succeeds silently */ }

        public String createInvoice(Id accountId, Decimal amount) {
            invoiceCalls.add(accountId + ':' + amount);
            if (accountId == failAccountId) {
