public class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> SObjectList) {
            return new Opportunities(SObjectList);
        }
    }

    public override void onBeforeInsert() {
        validateAmount();
    }

    public override void onBeforeUpdate() {
        validateAmount();
        validateWonOpportunityAmount();
    }

    private void validateAmount() {
        for (SObject record : this.records) {
            Opportunity opp = (Opportunity) record;
            if (opp.Amount != null && opp.Amount < 0) {
                error('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateWonOpportunityAmount() {
        Map<Id, SObject> oldMap = Trigger.oldMap;
        if (oldMap == null) return;

        for (SObject record : this.records) {
            Opportunity opp = (Opportunity) record;
            Opportunity oldOpp = (Opportunity) oldMap.get(opp.Id);

            if (oldOpp != null
                    && oldOpp.StageName == 'Closed Won'
                    && opp.Amount != oldOpp.Amount) {
                error('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
            }
        }
    }
}
