public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        Schema.FieldSet fs = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (fs != null) {
            Map<String, Schema.SObjectField> fieldMap =
                Schema.SObjectType.Account.fields.getMap();
            Set<Id> alreadyAdded = new Set<Id>();
            for (Schema.SObjectField f : fields) {
                alreadyAdded.add(f);
            }
            for (Schema.FieldSetMember fsm : fs.getAvailableFields()) {
                String fieldName = fsm.getFieldPath();
                if (fieldName.contains('.')) {
                    fieldName = fieldName.substringAfterLast('.');
                }
                Schema.SObjectField sf = fieldMap.get(fieldName.toLowerCase());
                if (sf != null && !alreadyAdded.contains(sf)) {
                    fields.add(sf);
                    alreadyAdded.add(sf);
                }
            }
        }

        return fields;
    }

    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField f : getSObjectFieldList()) {
            fieldNames.add(f.getDescribe().getName());
        }

        String soql = 'SELECT ' + String.join(fieldNames, ', ') +
                      ' FROM Account WITH USER_MODE WHERE Id IN :accountIds';

        return Database.query(soql);
    }

