        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName = 'Closed Won';
                opp.CloseDate = Date.today();
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // 3. One unit-of-work for the DML
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        uow.registerDirty(toClose);

        // 4. Build the events while the UoW is still open (none published yet)
        List<EventBus.BusableEvent> eventsToPublish = new List<EventBus.BusableEvent>();
        for (Opportunity opp : toClose) {
            eventsToPublish.add(new Deal_Won__e(
                Opportunity_Id__c = opp.Id,
                Amount__c         = opp.Amount
            ));
        }

        // 5. Single commit – if this throws, the exception propagates to the
        //    caller and the EventBus.publish line below is never reached,
        //    so Fulfilment never learns about an unsaved deal.
        uow.commit();

        // 6. DML committed successfully → publish the events now
        if (!eventsToPublish.isEmpty()) {
            EventBus.publish(eventsToPublish);
        }

        return toClose.size();
    }
