            SELECT StageName, SUM(Amount) total
            FROM Opportunity
            WHERE StageName IN :OPEN_STAGES
              AND CloseDate >= :fromDate
              AND CloseDate <= :toDate
            GROUP BY StageName
        ]) {
            String  stage = (String)  ar.get('StageName');
            Decimal total = (Decimal) ar.get('total');

            // SUM is null when every matching row has a null Amount → treat as 0
