/**
 * Closes stale (forgotten) opportunities by setting StageName to 'Closed Lost'.
 * Designed to be called synchronously from a Schedulable context.
 */
public with sharing class StaleOpportunityCloser {

    /**
     * Closes every open Opportunity whose CloseDate is strictly before {@code cutoff}.
     *
     * @param cutoff the boundary date; opportunities closing ON this date stay open
     * @return the number of opportunities whose stage was changed
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            return 0;
        }

        Integer closedCount = 0;

        // SOQL for-loop in list form: returns chunks of up to 200 rows.
        // IsClosed is a formula field (true when StageName is a closed stage),
        // so filtering on it is allowed in WHERE.
        for (List<Opportunity> chunk : [
                SELECT Id, StageName
                FROM Opportunity
                WHERE IsClosed = false
                  AND CloseDate < :cutoff
            ]) {

            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            // DML inside the loop keeps memory flat – only 200 records alive at a time.
            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
