/**
 * ErpCustomerSync
 *
 * • push()          – static gate called from AccountTrigger;
 *                     collects Ids and kicks off one async call.
 * • doSync()        – @future(callout=true) body that queries the
 *                     accounts, serialises a JSON array, and POSTs
 *                     to callout:ERP/api/customers.
 *
 * One HTTP request per trigger batch (1 → 200 accounts).
 * Error handling / retries intentionally out of scope.
 */
public with sharing class ErpCustomerSync {

    /** Prevents duplicate enqueueing within a single transaction. */
    private static Boolean dispatched = false;

    // ---------------------------------------------------------------
    //  Entry point (synchronous, trigger context)
    // ---------------------------------------------------------------
    public static void push(List<Account> accounts) {

        if (dispatched || accounts == null || accounts.isEmpty()) {
            return;
        }
        dispatched = true;

        List<Id> ids = new List<Id>(accounts.size());
        for (Account acct : accounts) {
            ids.add(acct.Id);
        }

        doSync(ids);
    }

    // ---------------------------------------------------------------
    //  Async execution – callout allowed via (callout=true)
    // ---------------------------------------------------------------
    @future(callout=true)
    public static void doSync(List<Id> accountIds) {

        // Bulk-safe: single SOQL regardless of batch size (1-200).
        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :accountIds
        ];

        // ---- Build JSON array payload ----
        List<Map<String, Object>> payload = new List<Map<String, Object>>(accounts.size());

        for (Account acct : accounts) {
            // BillingCountry → null when blank (per ERP contract).
            String country = String.isBlank(acct.BillingCountry)
                ? null
                : acct.BillingCountry;

            payload.add(new Map<String, Object>{
                'salesforceId' => (String) acct.Id,   // 18-char Id
                'name'         => acct.Name,
                'country'      => country               // null when blank
            });
        }

        // ---- Single POST to ERP via Named Credential ----
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(JSON.serialize(payload));
        req.setTimeout(120000);

        Http http = new Http();
        http.send(req);

        // 202 Accepted expected; error handling & retries out of scope.
    }
}
