/**
 * Creates a follow-up Task for every Opportunity passed in.
 *
 * All Tasks are built first, then inserted in a single
 * Database.insert(tasks, false) call (allOrNone = false).
 * That gives the same per-record isolation the individual
 * try/catch approach was meant to provide – a validation-rule
 * rejection on one Task does not prevent the others from
 * being created – while using only ONE DML statement, so
 * batches of 150–250 records stay well within the 150-DML
 * governor limit.
 *
 * Returns the set of Opportunity Ids whose Task could NOT be
 * created (empty set when every Task succeeded).
 */
public with sharing class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {

        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // ---- 1 SOQL (bulk-safe) ------------------------------------------
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            new List<Opportunity>(
                [
                    SELECT Id, Name, OwnerId
                    FROM   Opportunity
                    WHERE  Id IN :opportunityIds
                ]
            )
        );

        // ---- Build every Task, no DML yet --------------------------------
        //   oppIdsForTasks is a parallel list so we can map each SaveResult
        //   back to the originating Opportunity.
        List<Task> tasks           = new List<Task>();
        List<Id>   oppIdsForTasks  = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);

            // Id didn't resolve to an Opportunity (deleted, wrong SObject, etc.)
            if (opp == null) {
                failedOpportunityIds.add(oppId);
                continue;
            }

            Task t = new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status       = 'Not Started',
                Priority     = 'Normal'
            );

            tasks.add(t);
            oppIdsForTasks.add(opp.Id);
        }

        // ---- 1 DML: partial-success insert -------------------------------
        //   allOrNone = false  →  a failure on one row does NOT roll back
        //   the others; each SaveResult tells us per-row success/failure.
        if (!tasks.isEmpty()) {
            Database.SaveResult[] results = Database.insert(tasks, false);

            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    failedOpportunityIds.add(oppIdsForTasks[i]);
                }
            }
        }

        return failedOpportunityIds;
    }
}
