/**
 * OpportunityTrigger
 *
 * Fires after insert or after update when StageName / Amount changed.
 * Collects unique Account Ids, then delegates to a single async recalculation.
 *
 * Design note: one @future call per *batch*, not per record.
 * A 200-row CPQ batch on 200 distinct accounts would otherwise exceed the
 * 50-future-per-transaction governor limit.
 */
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    // Guard: skip if we are already inside another async context
    if (System.isBatch() || System.isFuture()) {
        return;
    }

    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    } else if (Trigger.isUpdate) {
        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.old[i];

            if (newOpp.AccountId == null) {
                continue;
            }

            if (newOpp.StageName != oldOpp.StageName ||
                newOpp.Amount != oldOpp.Amount) {

                accountIds.add(newOpp.AccountId);
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(accountIds);
    }
}
