/**
 * CaseTrigger – after-update handler.
 *
 * Detects cases that transition from open → closed (IsClosed false → true)
 * and have a ContactId.  Enqueues a CaseSurveyJob for the newly-closed cases.
 *
 * Platform limit: max 50 Queueable enqueue calls per transaction.
 * Agents closing bulk from list views and the nightly API cleanup (200 records)
 * would exceed that, so we chunk the IDs into groups of ≤ 50 and enqueue one
 * job per chunk.  Each chunk still executes in its own async transaction, so a
 * failure in one chunk cannot affect another.
 */
trigger CaseTrigger on Case (after update) {

    if (Trigger.isAfter && Trigger.isUpdate) {

        List<Id> newlyClosedCaseIds = new List<Id>();

        for (Case newCase : Trigger.new) {
            Case oldCase = Trigger.oldMap.get(newCase.Id);

            if (newCase.IsClosed
                && !oldCase.IsClosed
                && newCase.ContactId != null) {

                newlyClosedCaseIds.add(newCase.Id);
            }
        }

        if (newlyClosedCaseIds.isEmpty()) {
            return;
        }

        // Chunk into groups of ≤ 50 to respect the 50-Queueable-per-transaction
        // governor limit.  A 200-record close produces 4 jobs instead of a
        // LimitException.
        final Integer BATCH_SIZE = 50;
        Integer total = newlyClosedCaseIds.size();

        for (Integer i = 0; i < total; i += BATCH_SIZE) {
            Integer end = Math.min(i + BATCH_SIZE, total);
            List<Id> batch = new List<Id>();

            for (Integer j = i; j < end; j++) {
                batch.add(newlyClosedCaseIds[j]);
            }

            System.enqueueJob(new CaseSurveyJob(batch));
        }
    }
}
