/**
 * Queueable that creates a CSAT-survey Task for a batch of closed Cases.
 *
 * Runs asynchronously so that a future vendor survey callout can be added
 * without blocking the Case-update transaction.
 *
 * Database.AllowsCallouts is declared now to keep the trigger call-site
 * stable when the vendor integration lands.
 *
 * without sharing: the job may execute under an automation / integration
 * user whose sharing rules would otherwise hide records.
 */
public without sharing class CaseSurveyJob
        implements System.Queueable, Database.AllowsCallouts {

    private final List<Id> caseIds;

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds;
    }

    public void execute(System.QueueableContext ctx) {

        // Re-query at execution time – a case could theoretically be reopened
        // or have its ContactId cleared between trigger-fire and job-run.
        List<Case> closedCases = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id IN :caseIds
              AND IsClosed = true
              AND ContactId != null
            WITH USER_MODE
        ];

        if (closedCases.isEmpty()) {
            return;
        }

        List<Task> surveyTasks = new List<Task>(closedCases.size());

        for (Case c : closedCases) {
            Task t = new Task();
            t.WhatId       = c.Id;
            t.WhoId        = c.ContactId;
            t.Subject      = 'CSAT survey: ' + c.CaseNumber;
            t.ActivityDate = Date.today().addDays(2);
            t.Status       = 'Not Started';
            surveyTasks.add(t);
        }

        // Partial-success insert: one bad record does not roll back the rest.
        Database.insert(surveyTasks, false);
    }
}
