/**
 * Sends a renewal-reminder email to each Opportunity's owner.
 *
 * Designed to be called once per "sweep" of up to 200 Opportunities.
 * Each send is wrapped in its own try/catch so a single failure does not
 * prevent the remaining emails from being attempted.
 *
 * NOTE (see assessment commentary): 200 sequential sendEmail calls will
 * exceed the per-transaction email governor limit.  In production,
 * batch the messages (chunks of 10) or process via a Batchable class
 * with a batchSize <= 10.
 */
public with sharing class RenewalReminderService {

    /**
     * Sends one plain-text reminder email per Opportunity to its owner.
     *
     * @param opportunityIds  Ids of Opportunities whose renewal is due
     * @return number of emails that were accepted for delivery
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk query – one SOQL regardless of collection size.
        // Filter inactive owners / null owners here; they would only cause
        // a failure later and waste an email slot.
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM   Opportunity
            WHERE  Id       IN :opportunityIds
              AND  OwnerId  != null
              AND  Owner.IsActive = true
              AND  Owner.Email    != null
        ];

        Integer sentCount = 0;

        for (Opportunity opp : opps) {
            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();

                // Internal-user delivery: does not consume external-email allocation.
                email.setTargetObjectId(opp.OwnerId);

                // No need for a separate to-address; the User record supplies it.
                email.setSaveAsActivity(false);

                email.setSubject('Renewal due: ' + opp.Name);

                email.setPlainTextBody(
                    'Hello,\n\n'
                    + 'The renewal for "' + opp.Name + '" is due on '
                    + opp.CloseDate.format() + '.\n\n'
                    + 'Please take the necessary action before the close date.\n\n'
                    + '— Renewal Reminder Service'
                );

                // One send per Opportunity, as specified.
                // In production, batch these into groups of 10 instead.
                Messaging.SendEmailResult result =
                    Messaging.sendEmail(
                        new Messaging.SingleEmailMessage[] { email }
                    )[0];

                if (result.isSuccess()) {
                    sentCount++;
                }

            } catch (Exception e) {
                // Catch-all: inactive owner, invalid address, governor limit,
                // etc.  A LimitException is still fatal to the transaction,
                // but we guard against recoverable errors here.
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: could not send reminder for '
                    + opp.Id + ' (' + e.getMessage() + ')'
                );
            }
        }

        return sentCount;
    }
}
