```javascript
import { LightningElement, wire } from 'lwc';
import {
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE,
    MessageContext
} from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    subscription = null;
    recordId = null;

    @wire(MessageContext)
    context;

    /* ------------------------------------------------------------------ */
    /*  Lifecycle: subscribe on connect, unsubscribe on disconnect.       */
    /*  Re-insertion (e.g. tab reopen) re-enters connectedCallback and   */
    /*  subscribes again; disconnectedCallback always tears down first.  */
    /* ------------------------------------------------------------------ */

    connectedCallback() {
        if (!this.subscription) {
            this.subscription = subscribe(
                ACCOUNT_SELECTED,
                this.context,
                this.handleMessage,
                { scope: APPLICATION_SCOPE }
            );
        }
    }

    disconnectedCallback() {
        if (this.subscription) {
            unsubscribe(this.subscription, this.handleMessage);
            this.subscription = null;
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Message listener – stored as an arrow function so that            */
    /*  subscribe / unsubscribe receive the same function reference.      */
    /* ------------------------------------------------------------------ */

    handleMessage = (message) => {
        this.recordId = message.recordId;
    };

    /* ------------------------------------------------------------------ */
    /*  Clear-selection button                                             */
    /* ------------------------------------------------------------------ */

    handleClearSelection() {
        publish(ACCOUNT_SELECTED, this.context, { recordId: null });
    }
}
