import { LightningElement, track } from 'lwc';
import { getQueueStats } from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    @track _stats = null;
    _error = null;
    _inFlight = false;
    _timerId = null;
    _visibilityHandler = null;

    /* ---- computed properties consumed by the template ---- */

    get error() {
        return this._error;
    }

    get stats() {
        return this._stats;
    }

    get waiting() {
        return this._stats ? this._stats.waiting : null;
    }

    get longestWaitMinutes() {
        return this._stats ? this._stats.longestWaitMinutes : null;
    }

    get hasData() {
        return this._stats !== null && this._error === null;
    }

    /* ---- lifecycle ---- */

    connectedCallback() {
        // Fresh state in case the component is re-inserted
        this._stats = null;
        this._error = null;
        this._inFlight = false;
        this._timerId = null;

        // Listen for visibility changes
        this._visibilityHandler = () => { this._onVisibilityChange(); };
        document.addEventListener('visibilitychange', this._visibilityHandler);

        // Kick off only when the page is actually visible
        if (document.visibilityState !== 'hidden') {
            this._fetchAndStartTimer();
        }
    }

    disconnectedCallback() {
        this._stopTimer();
        if (this._visibilityHandler) {
            document.removeEventListener('visibilitychange', this._visibilityHandler);
            this._visibilityHandler = null;
        }
    }

    /* ---- private helpers ---- */

    _fetchAndStartTimer() {
        // Immediate load
        this._fetchStats();
        // Then every 60 seconds
        this._startTimer();
    }

    _startTimer() {
        this._stopTimer();
        this._timerId = setInterval(() => {
            // Safety check: don't fire while hidden
            if (document.visibilityState === 'hidden') { return; }
            this._fetchStats();
        }, 60000);
    }

    _stopTimer() {
        if (this._timerId != null) {
            clearInterval(this._timerId);
            this._timerId = null;
        }
    }

    _fetchStats() {
        // Never overlap requests
        if (this._inFlight) { return; }
        this._inFlight = true;

        getQueueStats()
            .then((result) => {
                this._stats = result;
                this._error = null;          // clear any previous error
            })
            .catch((error) => {
                this._error =
                    error?.body?.message || error?.message || String(error);
                // Keep previous stats visible? → no, requirement says remove error
                // after next success, implying error replaces the display.
                // We keep _stats as-is so the user sees the error instead.
            })
            .finally(() => {
                this._inFlight = false;
            });
    }

    _onVisibilityChange() {
        if (document.visibilityState === 'visible') {
            // Page just became visible: load immediately + restart 60 s cycle
            this._fetchAndStartTimer();
        } else {
            // Page is hidden: stop all polling
            this._stopTimer();
        }
    }
}
