/**
 * GiftImportService
 *
 * Stages one-off website gifts through NPSP's Batch Data Import (BDI) engine so that
 * NPSP's contact-matching, household-creation and donation-processing rules apply.
 * Each WebGift becomes one npsp__DataImport__c record that is then processed
 * synchronously via the org's BDI service.  The Data Import record remains in the
 * org as the audit trail of the import attempt.
 */
public with sharing class GiftImportService {

    // ──────────────────────────────────────────────────────────────────────────
    //  Input / output value objects
    // ──────────────────────────────────────────────────────────────────────────

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // matched-or-created Contact
        public Id opportunityId;    // created Donation (Opportunity)
        public String errorMessage; // NPSP failure text when success == false
    }

    // ──────────────────────────────────────────────────────────────────────────
    //  Public entry point
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Stages and processes one or more website gifts through NPSP BDI.
     *
     * @param  gifts  incoming gift payloads (may be null or empty)
     * @return        one ImportResult per input gift, in input order
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ── 1. Build staging records ─────────────────────────────────────────
        List<npsp__DataImport__c> stagedRecords = buildImportRecords(gifts);

        // ── 2. Persist all staging rows in a single DML (bulk-safe) ──────────
        try {
            insert stagedRecords;
        } catch (DmlException e) {
            return buildFailureResults(gifts.size(),
                'Data Import insert failed: ' + e.getMessage());
        }

        // ── 3. Hand off to NPSP's synchronous BDI service ───────────────────
        List<Id> importIds = new List<Id>(new Map<Id, npsp__DataImport__c>(stagedRecords).keySet());

        try {
            // NPSP BDI service – processes the passed-in records in the current
            // transaction.  Individual row-level rejections (Status → 'Failed')
            // are handled inside the engine; other rows continue to process.
            npsp.BDT_DataImport.importBatch(importIds);
        } catch (Exception systemicEx) {
            // A systemic blow-up (governor limit, internal NPSP error, etc.)
            // means nothing completed.  Report every gift as failed.
            return buildFailureResults(gifts.size(),
                'BDI processing error: ' + systemicEx.getMessage());
        }

        // ── 4. Read back the processed state for every staged row ────────────
        Map<Id, npsp__DataImport__c> resultMap = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c,
                   npsp__FailureInformation__c
            FROM   npsp__DataImport__c
            WHERE  Id IN :importIds
            WITH USER_MODE
        ]);

        // ── 5. Assemble ImportResult list in the caller's input order ────────
        List<ImportResult> results = new List<ImportResult>();
        for (npsp__DataImport__c di : stagedRecords) {
            ImportResult res = new ImportResult();
            npsp__DataImport__c processed = resultMap.get(di.Id);

            if (processed != null && processed.npsp__Status__c == 'Imported') {
                res.success       = true;
                res.contactId     = processed.npsp__Contact1Imported__c;
                res.opportunityId = processed.npsp__DonationImported__c;
            } else {
                res.success      = false;
                res.errorMessage = (processed != null)
                    ? (String.isNotBlank(processed.npsp__FailureInformation__c)
                        ? processed.npsp__FailureInformation__c
                        : 'No further detail')
                    : 'Data Import record not found after processing';
            }
            results.add(res);
        }

        return results;
    }

    // ──────────────────────────────────────────────────────────────────────────
    //  Private helpers
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Maps each WebGift to a fully-populated npsp__DataImport__c staging row.
     */
    private static List<npsp__DataImport__c> buildImportRecords(List<WebGift> gifts) {
        List<npsp__DataImport__c> records = new List<npsp__DataImport__c>(gifts.size());

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();

            // Contact staging – NPSP matches on First + Last + Personal Email
            di.npsp__Contact1_Firstname__c      = gift.firstName;
            di.npsp__Contact1_Lastname__c       = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;

            // Donation staging – never match existing donations (org setting)
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c   = gift.giftDate;
            di.npsp__Donation_Donor__c  = 'Contact1';

            records.add(di);
        }

        return records;
    }

    /**
     * Builds a uniform "all failed" result set (used when a systemic error
     * prevents BDI from running at all).
     */
    private static List<ImportResult> buildFailureResults(Integer count, String message) {
        List<ImportResult> failures = new List<ImportResult>();
        for (Integer i = 0; i < count; i++) {
            ImportResult res = new ImportResult();
            res.success      = false;
            res.errorMessage = message;
            failures.add(res);
        }
        return failures;
    }
}
