```apex
public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) return;

        // ── Collect unique IDs ──────────────────────────────────────────────
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ── SOQL 1: Opportunities (for validation) ─────────────────────────
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // ── SOQL 2: All Opportunity Contact Roles for these pairs ───────────
        Map<String, List<OpportunityContactRole>> ocrsByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
              AND ContactId     IN :contactIds
        ]) {
            String pairKey = ocr.OpportunityId + ':' + ocr.ContactId;
            if (!ocrsByPair.containsKey(pairKey)) {
                ocrsByPair.put(pairKey, new List<OpportunityContactRole>());
            }
            ocrsByPair.get(pairKey).add(ocr);
        }

        // ── SOQL 3: Existing Partial Soft Credits (minimal fields) ─────────
        Map<String, npsp__Partial_Soft_Credit__c> pscByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
              AND npsp__Contact__c     IN :contactIds
        ]) {
            pscByPair.put(
                psc.npsp__Opportunity__c + ':' + psc.npsp__Contact__c,
                psc
            );
        }

        // ── Validate BEFORE any DML ─────────────────────────────────────────
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);

            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + req.opportunityId);
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact on Opportunity ' + req.opportunityId);
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Amount must be positive for Opportunity ' + req.opportunityId +
                    ' / Contact ' + req.contactId);
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount +
                    ' exceeds Opportunity amount ' + opp.Amount +
                    ' for Opportunity ' + req.opportunityId);
            }
        }

        // ── Determine OCR operations ────────────────────────────────────────
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        // Resolved OCR (existing or newly-constructed) for each request index
        List<OpportunityContactRole> resolvedOcrs =
            new List<OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String pairKey = req.opportunityId + ':' + req.contactId;
            List<OpportunityContactRole> existing = ocrsByPair.get(pairKey);

            OpportunityContactRole match = null;

            if (existing != null) {
                for (OpportunityContactRole ocr : existing) {
                    if (ocr.Role == req.role) {
                        match = ocr;
                    } else {
                        // A role is being replaced – remove the old one
                        ocrsToDelete.add(ocr);
                    }
                }
            }

            if (match != null) {
                resolvedOcrs.add(match);
            } else {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                ocrsToInsert.add(newOcr);
                resolvedOcrs.add(newOcr);
            }
        }

        // ── DML 1: Delete conflicting OCRs ──────────────────────────────────
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // ── DML 2: Insert new OCRs ──────────────────────────────────────────
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // ── Build PSC operations ────────────────────────────────────────────
        List<npsp__Partial_Soft_Credit__c> pscsToInsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate =
            new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            OpportunityContactRole ocr = resolvedOcrs[i];

            String pairKey = req.opportunityId + ':' + req.contactId;
            npsp__Partial_Soft_Credit__c existing = pscByPair.get(pairKey);

            if (existing != null) {
                // Update with a fresh SObject carrying only the fields we change,
                // avoiding FLS issues with other fields (e.g. Contact_Name__c).
                npsp__Partial_Soft_Credit__c upd =
                    new npsp__Partial_Soft_Credit__c(
                        Id                         = existing.Id,
                        npsp__Amount__c            = req.amount,
                        npsp__Role_Name__c         = req.role,
                        npsp__Contact_Role_ID__c   = ocr.Id
                    );
                pscsToUpdate.add(upd);
            } else {
                pscsToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c   = req.opportunityId,
                    npsp__Contact__c       = req.contactId,
                    npsp__Amount__c        = req.amount,
                    npsp__Role_Name__c     = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                ));
            }
        }

        // ── DML 3: Insert new Partial Soft Credits ──────────────────────────
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }

        // ── DML 4: Update existing Partial Soft Credits ─────────────────────
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
