/**
 * Service to create NPSP Parent/Child relationship pairs.
 *
 * For each (child → parent) pair supplied, two npe4__Relationship__c records
 * are inserted:
 *   • child → parent  Type = 'Parent'
 *   • parent → child  Type = reciprocal from NPSP Relationship Lookup
 *
 * Because there is no standard "Gender" field on Contact in this org, the
 * reciprocal is resolved to the Neutral value ("Child") from the
 * npe4__Relationship_Lookup__c configuration for "Parent".  If the org
 * later adds a gender field the lookup logic can be extended without
 * changing the calling contract.
 *
 * Bulk-safe: at most 2 SOQL and 1 DML for up to 200 pairs.
 */
public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // ── guard ──────────────────────────────────────────────────────────────
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ── collect & validate IDs ─────────────────────────────────────────────
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // ── SOQL 1 – retrieve the NPSP Relationship Lookup for "Parent" ───────
        //    Gives us the configured reciprocal types without hard-coding.
        String reciprocalDefault = 'Child';

        npe4__Relationship_Lookup__c lookup = [
            SELECT npe4__Neutral__c
            FROM   npe4__Relationship_Lookup__c
            WHERE  Name            = 'Parent'
              AND  npe4__Active__c = TRUE
            LIMIT  1
        ];

        if (lookup != null && String.isNotBlank(lookup.npe4__Neutral__c)) {
            reciprocalDefault = lookup.npe4__Neutral__c;
        }

        // ── SOQL 2 – existing relationships among the contact set ──────────────
        //    Any relationship in EITHER direction causes the pair to be skipped,
        //    making the import idempotent / re-runnable.
        Set<String> existingPairKeys = new Set<String>();

        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM   npe4__Relationship__c
            WHERE  npe4__Contact__c       IN :allContactIds
              AND  npe4__RelatedContact__c IN :allContactIds
        ]) {
            // Store both directions so we can check in O(1)
            existingPairKeys.add(String.valueOf(rel.npe4__Contact__c) + ',' +
                                 String.valueOf(rel.npe4__RelatedContact__c));
        }

        // ── build new records (max 2 per valid pair) ───────────────────────────
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> batchPairKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null || childId == parentId) {
                continue;
            }

            // Two directional keys for this pair
            String childToParent = String.valueOf(childId)  + ',' + String.valueOf(parentId);
            String parentToChild = String.valueOf(parentId) + ',' + String.valueOf(childId);

            // Skip if a relationship already exists in the DB (either direction)
            if (existingPairKeys.contains(childToParent) ||
                existingPairKeys.contains(parentToChild)) {
                continue;
            }

            // Skip if already handled within this same batch (e.g. A↔B and B↔A)
            if (batchPairKeys.contains(childToParent) ||
                batchPairKeys.contains(parentToChild)) {
                continue;
            }

            batchPairKeys.add(childToParent);
            batchPairKeys.add(parentToChild);

            // Record A – child's view: "Parent"
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c           = 'Parent',
                npe4__Status__c         = 'Current'
            ));

            // Record B – parent's view: reciprocal (Son / Daughter / Child)
            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c        = parentId,
                npe4__RelatedContact__c = childId,
                npe4__Type__c           = reciprocalDefault,
                npe4__Status__c         = 'Current'
            ));
        }

        // ── DML (single statement) ─────────────────────────────────────────────
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
