/**
 * NPSP TDTM handler – OPP_MajorGiftFollowUp_TDTM
 *
 * Trigger Handler registration:
 *   Class         : OPP_MajorGiftFollowUp_TDTM
 *   Object        : Opportunity
 *   Trigger Action: AfterInsert;AfterUpdate
 *   Load Order    : 5
 *   Async         : false
 *
 * Behaviour:
 *   – On INSERT  : fires when StageName == 'Closed Won' AND Amount >= 5000.
 *   – On UPDATE  : fires only when the Opportunity BECOMES Closed Won +
 *                  Amount >= 5000 (i.e. it was NOT both before).
 *   – Editing a gift that already qualified creates no duplicate task.
 *
 * Governor-budget: 0 SOQL queries, 1 DML (bulk Task insert).
 */
public without sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal MAJOR_GIFT_THRESHOLD = 5000;
    private static final String  CLOSED_WON           = 'Closed Won';

    public override DmlWrapper run(
        List<SObject>                  newlist,
        List<SObject>                  oldlist,
        npsp.TDTM_Runnable.Action      triggerAction,
        Schema.DescribeSObjectResult   objResult
    ) {
        DmlWrapper dmlWrapper = new DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                if (isMajorGift(opp)) {
                    tasksToInsert.add(buildFollowUpTask(opp));
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            for (Integer i = 0; i < newlist.size(); i++) {
                Opportunity newOpp = (Opportunity) newlist[i];
                Opportunity oldOpp = (Opportunity) oldlist[i];

                Boolean nowQualifies  = isMajorGift(newOpp);
                Boolean wasQualifying = isMajorGift(oldOpp);

                // Only fire when the gift becomes newly qualifying.
                if (nowQualifies && !wasQualifying) {
                    tasksToInsert.add(buildFollowUpTask(newOpp));
                }
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    // ─── private helpers ────────────────────────────────────────────────

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= MAJOR_GIFT_THRESHOLD;
    }

    private static Task buildFollowUpTask(Opportunity opp) {
        Task t = new Task();
        t.Subject      = 'Major gift thank-you call';
        t.Priority     = 'High';
        t.Status       = 'Not Started';
        t.WhatId       = opp.Id;
        t.OwnerId      = opp.OwnerId;

        if (opp.npsp__Primary_Contact__c != null) {
            t.WhoId = opp.npsp__Primary_Contact__c;
        }

        if (opp.CloseDate != null) {
            t.ActivityDate = opp.CloseDate.addDays(3);
        }

        return t;
    }
}
