/**
 * Service class that returns FB_Employee__c records visible to the running user.
 * Enforces field-level security by excluding fields the user cannot read,
 * and enforces sharing (with sharing context).
 */
public with sharing class EmployeeDirectoryService {

    public static List<FB_Employee__c> getDirectory() {
        // If the running user has no read access to the object at all, return empty.
        if (!Schema.SObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        // Always include standard identifier / display fields.
        List<String> selectedFields = new List<String>{ 'Id', 'Name' };

        // Add custom fields only when the running user's FLS permits reading them.
        Schema.DescribeFieldResult deptDescribe =
            Schema.SObjectType.FB_Employee__c.fields.Department__c;
        Schema.DescribeFieldResult salaryDescribe =
            Schema.SObjectType.FB_Employee__c.fields.Salary__c;
        Schema.DescribeFieldResult emailDescribe =
            Schema.SObjectType.FB_Employee__c.fields.Personal_Email__c;

        if (deptDescribe.isAccessible()) {
            selectedFields.add('Department__c');
        }
        if (salaryDescribe.isAccessible()) {
            selectedFields.add('Salary__c');
        }
        if (emailDescribe.isAccessible()) {
            selectedFields.add('Personal_Email__c');
        }

        // Build the SOQL dynamically so only FLS-eligible fields appear.
        // The 'with sharing' class modifier already enforces OWD (Private)
        // and all active sharing rules.
        String soql = 'SELECT ' + String.join(selectedFields, ', ')
                    + ' FROM FB_Employee__c'
                    + ' ORDER BY Name ASC';

        return Database.query(soql);
    }
}
