```apex
/**
 * Bulk service that reassigns Accounts and their Contacts to a new owner.
 * Account trigger actions are bypassed for the duration of this method;
 * Contact trigger actions run normally.
 */
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Bypass ALL Account trigger actions for this transaction segment
        TriggerBase.bypass('Account');

        try {
            // SOQL #1: retrieve child Contacts (single bulk query)
            List<Contact> contacts = [
                SELECT Id, OwnerId
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            // Build lightweight Account records for the ownership change
            List<Account> accounts = new List<Account>();
            for (Id accId : accountIds) {
                accounts.add(new Account(Id = accId, OwnerId = newOwnerId));
            }

            // DML #1: update Accounts (Account triggers bypassed)
            if (!accounts.isEmpty()) {
                Database.update(accounts, true);
            }

            // Set OwnerId on Contacts so the update is a real change
            if (!contacts.isEmpty()) {
                for (Contact c : contacts) {
                    c.OwnerId = newOwnerId;
                }

                // DML #2: update Contacts (Contact triggers run normally)
                Database.update(contacts, true);
            }

        } finally {
            // Always restore Account automation, even on exception
            TriggerBase.clearBypass('Account');
        }
    }
}
