public with sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        execute((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        execute((List<Contact>) triggerNew, (List<Contact>) triggerOld);
    }

    private void execute(List<Contact> newRecords, List<Contact> oldRecords) {
        if (newRecords == null || newRecords.isEmpty()) {
            return;
        }

        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        if (oldRecords != null && !oldRecords.isEmpty()) {
            oldMap.putAll(oldRecords);
        }

        // ---- Identify records that need the duplicate-email check ----
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : newRecords) {
            // Skip records that lack an Account or an Email
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }

            // On update, skip if neither Email nor AccountId changed
            if (oldMap.containsKey(c.Id)) {
                Contact old = oldMap.get(c.Id);
                Boolean emailChanged = (old.Email == null && c.Email != null)
                    || (old.Email != null && c.Email != null
                        && !old.Email.toLowerCase().equals(c.Email.toLowerCase()));
                Boolean accountChanged = old.AccountId != c.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }

            toCheck.add(c);
            accountIds.add(c.AccountId);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // ---- Single SOQL query: all contacts on the relevant accounts ----
        // Build a lookup key = AccountId + '|' + lowercased Email
        Map<String, Set<Id>> existingByEmailKey = new Map<String, Set<Id>>();

        for (Contact existing : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
        ]) {
            if (String.isBlank(existing.Email)) {
                continue;
            }
            String key = existing.AccountId + '|' + existing.Email.toLowerCase();
            if (!existingByEmailKey.containsKey(key)) {
                existingByEmailKey.put(key, new Set<Id>());
            }
            existingByEmailKey.get(key).add(existing.Id);
        }

        // ---- Walk records in trigger-list order; first occurrence wins ----
        Set<String> claimedKeys = new Set<String>();

        for (Contact c : toCheck) {
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            Boolean hasConflict = false;

            // Conflict with an already-persisted contact (excluding self)?
            Set<Id> dbIds = existingByEmailKey.get(key);
            if (dbIds != null) {
                if (c.Id != null) {
                    dbIds.remove(c.Id);
                }
                if (!dbIds.isEmpty()) {
                    hasConflict = true;
                }
            }

            // Conflict with an earlier record accepted in this same save?
            if (!hasConflict && claimedKeys.contains(key)) {
                hasConflict = true;
            }

            if (hasConflict) {
                c.addError(ERROR_MESSAGE);
            } else {
                claimedKeys.add(key);
            }
        }
    }
}
