/**
 * Trigger Action (TAF) that maintains FB_Open_Case_Count__c on Account.
 * Counts Cases where IsClosed = false for every affected Account after
 * insert, update, delete or undelete of Cases.
 *
 * Budget: ≤ 2 SOQL queries, 1 DML per trigger execution.
 */
public with sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    // ---- After Insert ---------------------------------------------------
    public void afterInsert(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) return;

        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            Case c = (Case) s;
            if (c.AccountId != null && !c.IsClosed) {
                accountIds.add(c.AccountId);
            }
        }
        recalcAndCommit(accountIds);
    }

    // ---- After Update ---------------------------------------------------
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) return;

        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];

            Boolean newIsOpen = !newCase.IsClosed;
            Boolean oldIsOpen = !oldCase.IsClosed;

            if (!newIsOpen && !oldIsOpen) {
                // Both closed – no impact on any open count
                continue;
            }

            if (newIsOpen && oldIsOpen) {
                // Both open – only affected when the parent Account changes
                if (newCase.AccountId != oldCase.AccountId) {
                    if (newCase.AccountId != null) {
                        accountIds.add(newCase.AccountId);
                    }
                    if (oldCase.AccountId != null) {
                        accountIds.add(oldCase.AccountId);
                    }
                }
            } else if (newIsOpen) {
                // Closed → Open: new parent gains an open case
                if (newCase.AccountId != null) {
                    accountIds.add(newCase.AccountId);
                }
            } else {
                // Open → Closed: old parent loses an open case
                if (oldCase.AccountId != null) {
                    accountIds.add(oldCase.AccountId);
                }
            }
        }
        recalcAndCommit(accountIds);
    }

    // ---- After Delete ---------------------------------------------------
    public void afterDelete(List<SObject> triggerOld) {
        if (triggerOld == null || triggerOld.isEmpty()) return;

        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerOld) {
            Case c = (Case) s;
            if (c.AccountId != null && !c.IsClosed) {
                accountIds.add(c.AccountId);
            }
        }
        recalcAndCommit(accountIds);
    }

    // ---- After Undelete -------------------------------------------------
    public void afterUndelete(List<SObject> triggerNew) {
        if (triggerNew == null || triggerNew.isEmpty()) return;

        Set<Id> accountIds = new Set<Id>();
        for (SObject s : triggerNew) {
            Case c = (Case) s;
            if (c.AccountId != null && !c.IsClosed) {
                accountIds.add(c.AccountId);
            }
        }
        recalcAndCommit(accountIds);
    }

    // ---- Shared logic: 1 SOQL + 1 DML ----------------------------------
    private void recalcAndCommit(Set<Id> accountIds) {
        if (accountIds.isEmpty()) return;

        // SOQL #1 – aggregate current open-case count per affected Account
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
              FROM Case
             WHERE AccountId IN :accountIds
               AND IsClosed = false
             GROUP BY AccountId
        ]) {
            openCountByAccount.put(
                (Id) ar.get('AccountId'),
                (Integer) ar.get('cnt')
            );
        }

        // DML #1 – write the correct count (0 when no open cases remain)
        List<Account> toUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Integer count = openCountByAccount.containsKey(accId)
                ? openCountByAccount.get(accId)
                : 0;
            toUpdate.add(new Account(Id = accId, FB_Open_Case_Count__c = count));
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
