public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        TA_Contact_Queries queries = TA_Contact_Queries.getInstance();

        for (SObject sobj : triggerNew) {
            Contact c = (Contact) sobj;
            if (c.AccountId == null) {
                continue;
            }

            // Only inherit if ALL four mailing fields are blank
            if (String.isNotBlank(c.MailingStreet) ||
                String.isNotBlank(c.MailingCity) ||
                String.isNotBlank(c.MailingPostalCode) ||
                String.isNotBlank(c.MailingCountry)) {
                continue;
            }

            Account acct = queries.accountsById.get(c.AccountId);
            if (acct == null) {
                continue;
            }

            c.MailingStreet = acct.BillingStreet;
            c.MailingCity = acct.BillingCity;
            c.MailingPostalCode = acct.BillingPostalCode;
            c.MailingCountry = acct.BillingCountry;
        }
    }
}
